import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing, Img } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');

// Library: none — native interpolate and CSS 3D transforms for the web screen tilt

const { fontFamily: interFamily } = loadInter();



export type WebScreenTiltProps = Record<string, any>;

const LockIcon = ({ size, color }: { size: number; color: string }) => (
  <svg 
    width={size} 
    height={size} 
    viewBox="0 0 24 24" 
    fill="none" 
    stroke={color} 
    strokeWidth="2" 
    strokeLinecap="round" 
    strokeLinejoin="round" 
    style={{ transition: "none" }}
  >
    <rect x="3" y="11" width="18" height="11" rx="2" ry="2" style={{ transition: "none" }} />
    <path d="M7 11V7a5 5 0 0 1 10 0v4" style={{ transition: "none" }} />
  </svg>
);

const WebScreenTilt: React.FC<WebScreenTiltProps> = ({
  backgroundColor = "#1c449b",
  transparentBackground = false,
  durationInSeconds = 8,
  screenshotUrl = "https://images.unsplash.com/photo-1551288049-bebda4e38f71?q=80&w=1200&auto=format&fit=crop",
  websiteUrl = "yourwebsite.com",
  websiteUrlFontFamily = "Inter"
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Timings and Progress
  const totalFrames = fps * durationInSeconds;
  
  // Fast smooth entrance over the first 1.5 seconds
  const entranceProgress = interpolate(frame, [0, fps * 1.5], [0, 1], {
    easing: Easing.out(Easing.cubic),
    extrapolateRight: "clamp"
  });

  // Slow continuous tilt flattening out over the entire duration
  const slowTiltProgress = interpolate(frame, [0, totalFrames], [0, 1], {
    easing: Easing.out(Easing.ease),
    extrapolateRight: "clamp"
  });

  // Compose the rotations: fly in with extreme angles, settle to moderate, then slowly flatten to 0
  const rotX = interpolate(entranceProgress, [0, 1], [40, 15]) - interpolate(slowTiltProgress, [0, 1], [0, 15]);
  const rotY = interpolate(entranceProgress, [0, 1], [-45, -25]) - interpolate(slowTiltProgress, [0, 1], [0, -25]);
  const rotZ = interpolate(entranceProgress, [0, 1], [-10, -5]) - interpolate(slowTiltProgress, [0, 1], [0, -5]);
  
  // Scale dynamically to fill the view as it faces forward
  const scale = interpolate(entranceProgress, [0, 1], [0.5, 0.85]) + interpolate(slowTiltProgress, [0, 1], [0, 0.15]);
  
  // Fade in to avoid harsh start
  const opacity = interpolate(frame, [0, 15], [0, 1], { 
    extrapolateRight: "clamp" 
  });

  // Responsive Window Sizing (using main axes)
  const windowWidth = width * 0.75;
  const windowHeight = height * 0.83;

  // 3D Extrusion setup
  const extrusionLayers = 24;
  const extrusionDepth = 1.5 * s;

  const layers = Array.from({ length: extrusionLayers }).map((_, i) => {
    const isBack = i === extrusionLayers - 1;
    return (
      <div
        key={i}
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          width: windowWidth,
          height: windowHeight,
          background: isBack ? "#cccccc" : "#e6e6e6",
          borderRadius: 24 * s,
          transform: `translateZ(${-i * extrusionDepth}px)`,
          boxShadow: isBack ? `0px ${30 * s}px ${60 * s}px rgba(0,0,0,0.4)` : "none",
          transition: "none"
        }}
      />
    );
  });

  const fontFamilyMap: Record<string, string> = {
    Inter: interFamily
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, display: "flex", alignItems: "center", justifyContent: "center", transition: "none" }}>
      <div 
        style={{
          perspective: width * 1.5,
          transformStyle: "preserve-3d",
          width: windowWidth,
          height: windowHeight,
          opacity,
          transition: "none"
        }}
      >
        <div 
          style={{
            width: "100%",
            height: "100%",
            transformStyle: "preserve-3d",
            transform: `scale(${scale}) rotateX(${rotX}deg) rotateY(${rotY}deg) rotateZ(${rotZ}deg)`,
            transition: "none"
          }}
        >
          {/* Extruded Sides */}
          {layers}
          
          {/* Front Face */}
          <div 
            style={{
              position: "absolute",
              top: 0,
              left: 0,
              width: windowWidth,
              height: windowHeight,
              background: "white",
              borderRadius: 24 * s,
              transform: `translateZ(0px)`,
              display: "flex",
              flexDirection: "column",
              overflow: "hidden",
              boxShadow: `inset 0 0 0 ${1 * s}px rgba(0,0,0,0.05)`,
              transition: "none"
            }}
          >
            {/* Browser Chrome / Header */}
            <div 
              style={{
                height: 60 * s,
                background: "#f5f5f5",
                display: "flex",
                alignItems: "center",
                padding: `0 ${20 * s}px`,
                position: "relative",
                flexShrink: 0,
                borderBottom: `${1 * s}px solid rgba(0,0,0,0.05)`,
                transition: "none"
              }}
            >
              {/* Window Controls */}
              <div style={{ display: "flex", gap: 8 * s, flex: 1, transition: "none" }}>
                <div style={{ width: 12 * s, height: 12 * s, borderRadius: "50%", background: "#ff5f56", transition: "none" }} />
                <div style={{ width: 12 * s, height: 12 * s, borderRadius: "50%", background: "#ffbd2e", transition: "none" }} />
                <div style={{ width: 12 * s, height: 12 * s, borderRadius: "50%", background: "#27c93f", transition: "none" }} />
              </div>
              
              {/* Address Bar */}
              <div 
                style={{
                  background: "white",
                  padding: `${6 * s}px ${16 * s}px`,
                  borderRadius: 12 * s,
                  display: "flex",
                  alignItems: "center",
                  gap: 8 * s,
                  width: "40%",
                  justifyContent: "center",
                  boxShadow: `0 ${1 * s}px ${2 * s}px rgba(0,0,0,0.05)`,
                  transition: "none"
                }}
              >
                <LockIcon size={12 * s} color="#666" />
                <div 
                  style={{ 
                    fontSize: 14 * s, 
                    color: "#333", 
                    fontFamily: fontFamilyMap[websiteUrlFontFamily],
                    fontWeight: 500,
                    transition: "none",
                    whiteSpace: "nowrap",
                    overflow: "hidden",
                    textOverflow: "ellipsis"
                  }}
                >
                  {websiteUrl}
                </div>
              </div>

              {/* Right Spacer for balance */}
              <div style={{ flex: 1, transition: "none" }} />
            </div>
            
            {/* Screenshot Area */}
            <div style={{ flex: 1, position: "relative", background: "#fff", transition: "none" }}>
              {screenshotUrl ? (
                <Img 
                  src={screenshotUrl} 
                  style={{ 
                    width: "100%", 
                    height: "100%", 
                    objectFit: "cover", 
                    objectPosition: "top",
                    transition: "none" 
                  }} 
                />
              ) : (
                <div 
                  style={{ 
                    width: "100%", 
                    height: "100%", 
                    background: "#fafafa", 
                    display: "flex", 
                    alignItems: "center", 
                    justifyContent: "center", 
                    color: "#ccc", 
                    fontFamily: interFamily, 
                    transition: "none" 
                  }}
                >
                  No screenshot provided
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default WebScreenTilt;